{
  "cvars": {
    "ivs": [
      {
        "description": "Applicant gender indicator (1 = female, 0 = male). This is the primary independent variable of interest: How being female affects the probability of mortgage approval.",
        "columns": [
          "Female"
        ]
      }
    ],
    "dv": {
      "description": "Whether the mortgage application was approved (1 = approved/accepted, 0 = denied). Binary dependent variable representing lender decision.",
      "columns": [
        "Approved"
      ]
    },
    "controls": [
      {
        "description": "Whether the applicant is Black (1 = Black, 0 = not Black). Included both as a control for applicant race and as a moderator to test whether the gender effect differs by race.",
        "is_moderator": true,
        "moderator_on": "Female",
        "columns": [
          "Black"
        ]
      },
      {
        "description": "Loan or request size (original dataset column feature1). Continuous control for loan magnitude.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "LoanAmount",
          "LoanAmount_z"
        ]
      },
      {
        "description": "Housing expense as a ratio of total income (feature4). Continuous control capturing housing burden.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "HousingExpenseRatio",
          "HousingExpenseRatio_z"
        ]
      },
      {
        "description": "Indicator for self-employment (1 = self-employed, 0 = not). Control for employment type (feature5).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "SelfEmployed"
        ]
      },
      {
        "description": "Indicator for marital status (1 = married, 0 = not). Control for household/relationship context (feature6).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Married"
        ]
      },
      {
        "description": "Applicant's mortgage credit score (ordinal numeric 1-4, feature7). Control for creditworthiness.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "MortCreditScore"
        ]
      },
      {
        "description": "Applicant's consumer credit score (ordinal numeric 1-6, feature8). Control for creditworthiness.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "ConsCreditScore"
        ]
      },
      {
        "description": "Indicator for prior bad credit history (1 = has history of bad credit, 0 = no). Control for credit risk (feature9).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "BadCreditHistory"
        ]
      },
      {
        "description": "Total debt payments to income ratio (feature10). Continuous control for overall indebtedness.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "DebtToIncome",
          "DebtToIncome_z"
        ]
      },
      {
        "description": "Loan-to-value ratio: ratio of loan amount to appraised value (feature12). Continuous control for collateral risk.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "LTV",
          "LTV_z"
        ]
      },
      {
        "description": "Indicator that private mortgage insurance was denied (feature13). Control for underwriting outcomes.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "DeniedPMI"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Transform raw dataset into analysis-ready dataframe with clear column names and derived variables.\n\n    Final returned dataframe will contain at least the following columns used in modeling:\n      - Female (0/1)\n      - Approved (0/1)\n      - Black (0/1)\n      - Female_Black (interaction: Female * Black)\n      - LoanAmount, LoanAmount_z\n      - HousingExpenseRatio, HousingExpenseRatio_z\n      - DebtToIncome, DebtToIncome_z\n      - LTV, LTV_z\n      - SelfEmployed, Married, MortCreditScore, ConsCreditScore, BadCreditHistory, DeniedPMI\n    \"\"\"\n    df = df.copy()\n\n    # Columns required from the input (based on schema)\n    required_raw = ['feature1','feature2','feature3','feature4','feature5','feature6','feature7','feature8','feature9','feature10','feature12','feature13','feature14']\n    # Drop rows missing any of these required predictors / outcome\n    df = df.dropna(subset=required_raw)\n\n    # Rename columns to meaningful analysis names\n    df = df.rename(columns={\n        'feature2': 'Female',            # 1 if female, 0 if male\n        'feature14': 'Approved',         # 1 if accepted, 0 if denied (dependent variable)\n        'feature3': 'Black',             # 1 if Black\n        'feature1': 'LoanAmount',\n        'feature4': 'HousingExpenseRatio',\n        'feature5': 'SelfEmployed',\n        'feature6': 'Married',\n        'feature7': 'MortCreditScore',\n        'feature8': 'ConsCreditScore',\n        'feature9': 'BadCreditHistory',\n        'feature10': 'DebtToIncome',\n        'feature12': 'LTV',\n        'feature13': 'DeniedPMI'\n    })\n\n    # Ensure integer indicator columns are ints (0/1)\n    indicators = ['Female','Approved','Black','SelfEmployed','Married','BadCreditHistory','DeniedPMI']\n    for col in indicators:\n        # cast safe: round then astype int in case of floats like 0.0/1.0\n        df[col] = pd.to_numeric(df[col], errors='coerce').round().astype(int)\n\n    # Ensure scores are numeric\n    df['MortCreditScore'] = pd.to_numeric(df['MortCreditScore'], errors='coerce')\n    df['ConsCreditScore'] = pd.to_numeric(df['ConsCreditScore'], errors='coerce')\n\n    # Create interaction term for moderation tests\n    df['Female_Black'] = df['Female'] * df['Black']\n\n    # Standardize continuous covariates used in the model (z-scores). Use sample std (ddof=1) via pandas .std().\n    continuous = ['LoanAmount','HousingExpenseRatio','DebtToIncome','LTV']\n    for col in continuous:\n        # If constant (std == 0) then create z as 0 to avoid division by zero\n        col_series = pd.to_numeric(df[col], errors='coerce')\n        mean = col_series.mean()\n        std = col_series.std()\n        if pd.isna(std) or std == 0:\n            df[col + '_z'] = 0.0\n        else:\n            df[col + '_z'] = (col_series - mean) / std\n\n    # Final safety drop: ensure no missing values remain in modeling columns\n    model_cols = ['Female','Approved','Black','Female_Black','LoanAmount_z','HousingExpenseRatio_z','DebtToIncome_z','LTV_z',\n                  'SelfEmployed','Married','MortCreditScore','ConsCreditScore','BadCreditHistory','DeniedPMI']\n    df = df.dropna(subset=model_cols)\n\n    # Return transformed dataframe\n    return df\n",
  "m_code": "def model(df: pd.DataFrame):\n    \"\"\"\n    Fit a logistic regression (logit) predicting Approved (1 = accepted) from Female and controls.\n\n    The model includes an interaction Female_Black to test whether the gender effect differs for Black applicants.\n    Returns the fitted statsmodels Logit result object.\n    \"\"\"\n    df = df.copy()\n\n    # Dependent and independent columns used in the model\n    y = df['Approved']\n\n    X_cols = [\n        'Female',\n        'Black',\n        'Female_Black',\n        # standardized continuous controls\n        'LoanAmount_z',\n        'HousingExpenseRatio_z',\n        'DebtToIncome_z',\n        'LTV_z',\n        # other controls\n        'SelfEmployed',\n        'Married',\n        'MortCreditScore',\n        'ConsCreditScore',\n        'BadCreditHistory',\n        'DeniedPMI'\n    ]\n\n    X = df[X_cols]\n    # Add constant for intercept\n    X = sm.add_constant(X, has_constant='add')\n\n    # Fit logistic regression using statsmodels Logit\n    # Use disp=False to suppress fitting output; the returned result contains full summary\n    logit_model = sm.Logit(y, X)\n    results = logit_model.fit(disp=False)\n\n    # Return the fitted results object (results.summary() can be printed by the caller)\n    return results\n"
}

